import type {CopilotChatEntitlementQuotas} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {sendEvent} from '@github-ui/hydro-analytics'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'

import {Service, Status, useWorkbenchStore} from '../contexts/WorkbenchStoreContext'
import type {WorkbenchRoutePayload} from '../types/workbench-types'
import {CopilotLicenseType, CopilotPlan, EntitledService, initialState} from '../utilities/workbench-store-reducer'
import {BannerType} from '../utilities/workspace-editor-types'
import {useConcurrentSparks} from './use-concurrent-sparks'
import {useOptionalServerEvents as useServerEvents} from './use-optional-server-events'
import {useSparkIdle} from './use-spark-idle'

export function useBannerState(): BannerType | null {
  const {entitlement, status} = useWorkbenchStore()
  const isIdle = useSparkIdle()
  // This will never throw, even if no provider is mounted, like on the Spark dashboard
  const {errors} = useServerEvents()
  const concurrentSparks = useConcurrentSparks()
  const payload = useRoutePayload<WorkbenchRoutePayload>() || {}
  const runtimePermanentName = payload.workbench?.runtime?.app?.permanentName
  const activeSparks = concurrentSparks?.activeSparks
  const currentSparkIsActive = Boolean(
    runtimePermanentName && activeSparks?.some(s => s.runtime.app.permanentName === runtimePermanentName),
  )

  // Copilot chat quota
  const copilot = entitlement?.[EntitledService.COPILOT] ?? initialState.entitlement[EntitledService.COPILOT]
  const {
    plan,
    licenseType,
    // eslint-disable-next-line @typescript-eslint/no-unnecessary-type-assertion
    quotas = initialState.entitlement[EntitledService.COPILOT].quotas as CopilotChatEntitlementQuotas,
  } = copilot
  const {remaining, overagesEnabled} = quotas

  const isLicensedLimited = licenseType === CopilotLicenseType.LicensedLimited
  const isPaidPlan =
    plan === CopilotPlan.IndividualPro ||
    plan === CopilotPlan.IndividualProPlus ||
    plan === CopilotPlan.Business ||
    plan === CopilotPlan.Enterprise ||
    plan === CopilotPlan.IndividualStudent // not actually paid but we want things to work the same

  const chatQuotaExceeded = (remaining.chatPercentage ?? 0) <= 0
  const chatQuotaRemaining = remaining.chatPercentage ?? 0
  const chatQuotaApproaching = chatQuotaRemaining <= 50 && chatQuotaRemaining > 0
  const premiumInteractionsQuotaExceeded = (remaining.premiumInteractionsPercentage ?? 0) <= 0
  const premiumChatQuotaRemaining = remaining.premiumInteractionsPercentage ?? 0
  const premiumInteractionsQuotaApproaching = premiumChatQuotaRemaining <= 20 && premiumChatQuotaRemaining > 0

  const isQuotaApproaching =
    (isLicensedLimited && chatQuotaApproaching) || (isPaidPlan && premiumInteractionsQuotaApproaching)
  const isQuotaExceeded = (isLicensedLimited && chatQuotaExceeded) || (isPaidPlan && premiumInteractionsQuotaExceeded)

  const codespaceSessionsAllowed = entitlement?.[EntitledService.CODESPACE_SESSIONS].allowed
  const concurrentSparksExceeded = !codespaceSessionsAllowed && !currentSparkIsActive && (activeSparks?.length ?? 0) > 0
  const computeRemaining = entitlement?.[EntitledService.CODESPACE_COMPUTE].quotas.remaining.computeHoursPercentage > 0

  const hasBillingAssignmentIssue = entitlement?.[EntitledService.BILLING_STATUS]?.status === 'MissingCustomer'

  const hasBillingIssues = entitlement?.[EntitledService.BILLING_STATUS]?.canProceed === false

  // @see: spark-agent/src/server/errors.ts
  const isRateLimited = errors.some(e => e.statusCode === 429)
  const isOverageLimitReached = errors.some(e => e.statusCode === 402)

  // User is rate limited
  if (isRateLimited) {
    sendEvent('workbench.spark_usage_blocked', {
      numPrompts: (payload.workbench?.previousRefinements?.length ?? 0) + 1, // +1 for the current prompt
      plan,
      reason: 'capacity_user_rate_limited',
      sparkId: payload.workbench?.id,
    })
    return BannerType.USER_RATE_LIMITED
  }

  if (hasBillingAssignmentIssue) {
    return BannerType.COPILOT_BILLING_MEMBERSHIP
  }

  // Billing issues
  if (hasBillingIssues && isQuotaExceeded) {
    return BannerType.COPILOT_BILLING
  }

  // Upgrade flows
  if (isQuotaExceeded || isQuotaApproaching || isOverageLimitReached) {
    // Show the Compute Limit banner when the user has no dev compute remaining AND if either of the following conditions are met:
    // 1. The user has exceeded their chat quota and has LicensedFull with overages enabled, OR
    // 2. The user has chat quota approaching
    if (
      (isQuotaApproaching || (isQuotaExceeded && licenseType === CopilotLicenseType.LicensedFull && overagesEnabled)) &&
      !computeRemaining
    ) {
      return BannerType.COMPUTE_LIMIT
    }

    // Show the concurrent sparks banner when the user has multiple open sparks (>1 for Free and >10 for Paid plans) AND
    // if either of the following conditions are met:
    // 1. The user has exceeded their chat quota and has LicensedFull with overages enabled, OR
    // 2. The user has chat quota approaching
    if (
      (isQuotaApproaching || (isQuotaExceeded && licenseType === CopilotLicenseType.LicensedFull && overagesEnabled)) &&
      concurrentSparksExceeded
    ) {
      return BannerType.MULTIPLE_SPARKS
    }

    if (isOverageLimitReached) {
      sendEvent('workbench.spark_usage_blocked', {
        numPrompts: (payload.workbench?.previousRefinements?.length ?? 0) + 1, // +1 for the current prompt
        plan,
        reason: 'capacity_overage_limit_reached',
        sparkId: payload.workbench?.id,
      })
    }

    return BannerType.COPILOT_CHAT_QUOTA
  }

  // Concurrent Sparks exceeded
  if (concurrentSparksExceeded) {
    return BannerType.MULTIPLE_SPARKS
  }

  // Compute limit
  if (!computeRemaining) {
    return BannerType.COMPUTE_LIMIT
  }

  // Spark is left idle for too long
  if (isIdle && status[Service.CODESPACE] === Status.IDLE) {
    return BannerType.IDLE_SPARK
  }

  return null
}
