import {useCallback} from 'react'

import {uuid} from '../utilities/uuid'
import {useAnalyticsContext} from './AnalyticsContext'
import {createSendAnalyticsEvent} from './Event'
import type {SendAnalyticsEventFunction} from './interfaces'

/**
 * Returns a function for sending telemetry events assigned to Spark + attaches the
 * current analytics context metadata to the event.
 */
export function useAnalytics(): SendAnalyticsEventFunction {
  const metadata = useAnalyticsContext()

  return useCallback((eventName, properties) => createSendAnalyticsEvent(metadata)(eventName, properties), [metadata])
}

export type UserType = 'human' | 'agent'

/**
 * Any location where we allow users to edit the Spark contents, via AI or not,
 * we track together through `change_started` and `change_completed` events.
 * This hook handles simple cases consistently with minimal boilerplate.
 *
 * @param method The method used for iteration, e.g., 'refine', 'generate', etc.
 * @returns functions for recording the start, success, and error of an iteration process.
 */
export function useIterateAnalytics(method: string) {
  const sendEvent = useAnalytics()

  const iterateStarted = useCallback(
    (userType: UserType = 'human') => {
      const telemetryProperties = {
        iteration_start_time: Date.now(),
        iteration_step: 'refine',
        iteration_method: method,
        iteration_uuid: uuid(),
        user_type: userType,
      }

      sendEvent('change_started', telemetryProperties)

      return telemetryProperties
    },
    [method, sendEvent],
  )

  const iterateError = useCallback(
    (errorMessage: string, errorCode: number, telemetryProperties: Record<string, unknown> = {}) => {
      const startTime = (telemetryProperties.iteration_start_time as number) || undefined
      sendEvent('change_completed', {
        ...telemetryProperties,
        time_to_iterate_ms: startTime ? Date.now() - startTime : 0,
        error_message: errorMessage,
        error_code: errorCode,
        success: false,
      })
    },
    [sendEvent],
  )

  const iterateSuccess = useCallback(
    (telemetryProperties: Record<string, unknown>) => {
      const startTime = (telemetryProperties.iteration_start_time as number) || undefined
      sendEvent('change_completed', {
        ...telemetryProperties,
        time_to_iterate_ms: startTime ? Date.now() - startTime : 0,
        success: true,
      })
    },
    [sendEvent],
  )

  return {
    iterateStarted,
    iterateError,
    iterateSuccess,
  }
}
