import safeStorage from '@github-ui/safe-storage'
import {SecretScanningAuthToken} from './token'

const SECRET_SCANNING_TOKEN_STORAGE_KEY = 'SECRET_SCANNING_AUTH_TOKEN'

type SecretScanningTokenResult = {
  secret_scanning_token: string
  secret_scanning_expiration: string
}

/**
 * SecretScanningTokenProvider handles safe storage and retrieval of secret scanning auth tokens.
 *
 * It provides a simple interface for storing/retrieving tokens with:
 * - Safe localStorage persistence
 * - Automatic expiration checking
 * - Token validation
 *
 * Note: This provider does NOT currently handle token fetching - that's done via the
 * /spark/runtime/token endpoint directly. This is only for storage management, until we have other means of fetching tokens.
 */
export class SecretScanningTokenProvider {
  #storageKey: string
  #storage: {
    getItem: (key: string, now?: number) => string | null
    setItem: (key: string, value: string, now?: number) => void
    removeItem: (key: string) => void
  }

  constructor(storageKey: string = SECRET_SCANNING_TOKEN_STORAGE_KEY) {
    this.#storageKey = storageKey
    this.#storage = safeStorage('localStorage', {
      throwQuotaErrorsOnSet: false,
      ttl: 1000 * 60 * 60 * 24,
    })
  }

  /**
   * Get the cached secret scanning token from storage, if it exists and is valid.
   * Returns null if no token exists, token is expired, or token is invalid.
   */
  getToken(): SecretScanningAuthToken | null {
    try {
      const value = this.#storage.getItem(this.#storageKey)
      if (!value) {
        return null
      }

      const token = SecretScanningAuthToken.deserialize(JSON.parse(value))

      // Return null if token is expired
      if (token.isExpired) {
        this.clearToken()
        return null
      }

      return token
    } catch (error) {
      // Rethrow error so it's reported to sentry
      setTimeout(() => {
        throw error
      }, 1000)

      // If there's any error parsing or deserializing, clear the bad token
      this.clearToken()
      return null
    }
  }

  /**
   * Store a secret scanning token in safe storage.
   */
  #storeToken(token: SecretScanningAuthToken): void {
    this.#storage.setItem(this.#storageKey, JSON.stringify(token.serialize()))
  }

  /**
   * Clear the cached token from storage.
   */
  clearToken(): void {
    try {
      this.#storage.removeItem(this.#storageKey)
    } catch (error) {
      // Ignore removal errors but rethrow so it's reported to sentry
      setTimeout(() => {
        throw error
      }, 1000)
    }
  }

  /**
   * Type guard to check if the response contains secret scanning token fields
   */
  #isSecretScanningTokenResult(data: unknown): data is SecretScanningTokenResult {
    return (
      typeof data === 'object' &&
      data !== null &&
      'secret_scanning_token' in data &&
      'secret_scanning_expiration' in data &&
      typeof (data as Record<string, unknown>).secret_scanning_token === 'string' &&
      typeof (data as Record<string, unknown>).secret_scanning_expiration === 'string'
    )
  }

  #tokenFromResult(result: SecretScanningTokenResult): SecretScanningAuthToken {
    return new SecretScanningAuthToken(result.secret_scanning_token, result.secret_scanning_expiration)
  }

  /**
   * Handle secret scanning token from API response data.
   * This method safely checks if the response contains secret scanning token data
   * and stores it if valid, doing nothing if the data is invalid or missing.
   */
  storeTokenFromResponse(responseData: unknown): void {
    if (this.#isSecretScanningTokenResult(responseData)) {
      if (responseData.secret_scanning_token !== '') {
        this.#storeToken(this.#tokenFromResult(responseData))
      }
    }
  }
}
