import {queryOptions, useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'

import type {Workbench} from '../types/workbench-types'

export const workbenchQueryOptions = (id: string) =>
  queryOptions({
    queryKey: ['workbench', id],
    queryFn: async () => {
      const res = await verifiedFetchJSON(`/copilot/spark/workbench/${id}`, {method: 'GET'})
      if (!res.ok) {
        throw new Error(`Failed to fetch workbench: ${res.status} ${res.statusText}`)
      }
      return (await res.json()) as Workbench
    },
  })

export const useWorkbenchQuery = (id: string, initialData: Workbench) => {
  return useQuery({
    ...workbenchQueryOptions(id),
    initialData,
  })
}
